new_words_text:
- name: confident_bypass_victim
  place: condition
  params: {rdp_table: table, conf_table: table, index: signature, div: {int: [1, 1024]}, conf_thresh: {int: [0, 3]}}
  means: >
    Reads the victim key of the chosen victim way. Reads the rdp_table entry at the given index;
    if absent, the value is 0. True if this rdp value, divided by div (integer division),
    is greater than the absolute value of the victim key, AND the entry in conf_table at the given
    index has a value greater than or equal to conf_thresh. This word can only be used in bypass_when.

description:
name: mj_conf_penalty
doc: >
  This policy builds on Mockingjay by adding a confidence mechanism to its reuse
  predictor. It adds a 2-bit confidence counter for each signature. On a sampler
  hit, confidence is increased; on a miss or timeout, it's decreased. On a cache
  fill, if the signature has low confidence, the line's initial ETR (Estimated
  Time to Reuse) is penalized, making it a more likely eviction candidate. This
  aims to reduce cache pollution by more quickly evicting lines with uncertain
  reuse, addressing the 'kept_dead' problem.

state:
  - name: etr
    scope: per_line
    kind: signed
    width: 5                  # holds -11..11
    init: 0
  - name: etr_clock
    scope: per_set
    kind: counter
    width: 4
    init: 8                   # GRANULARITY: the first access to a set ages it
  - name: set_clock
    scope: per_set
    kind: counter
    width: 8                  # TIMESTAMP_BITS; wraps by design
    init: ZERO

victim:
  key: etr
  extremum: max_magnitude
  tie_break: prefer_negative
  on_search: none
  bypass_when:                # the incoming line is predicted to be reused after every resident
    - {table: {table: rdp, index: pc_sig, cmp: gt, threshold: 73}}
    - {table_exceeds_victim: {table: rdp, index: pc_sig, div: 8}}

